import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Object3D, Color, sRGBEncoding } from 'three/webgpu';
import { texture, uv, vec4, mix, float } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Object3D();
  group.name = 'hub-pricing-title';

  const { position = [0, 3, 0], rotation = [0, 0, 0], scale = [1, 1, 1] } = config.scenePosition || {};

  const imageUrl = '/prism-mock/home/nodes/cta-hero-isolated.png';
  const map = ctx.textureLoader.load(imageUrl);

  const geometry = new PlaneGeometry(3.2, 2.0, 1, 1);
  const material = new MeshBasicNodeMaterial({ transparent: true });

  const tex = texture(map, uv());
  const grain = float(0.0);
  material.colorNode = mix(tex, vec4(new Color(0x16161d), 1.0), grain);

  const plane = new Mesh(geometry, material);
  group.add(plane);

  const textMeshes = [];
  const textContent = config.textContent || [
    { role: 'headline', text: 'Pricing', size: 96, weight: 400 }
  ];

  textContent.forEach((entry, i) => {
    const text = typeof entry === 'string' ? entry : entry.text;
    const role = (entry && entry.role) || 'headline';
    const mesh = ctx.fontAtlas.createText({
      text,
      font: 'display',
      weight: (entry && entry.weight) || 400,
      size: role === 'headline' ? 0.34 : 0.2,
      color: '#e8ecf2',
      align: 'center'
    });
    mesh.position.set(0, 0, 0.01 + i * 0.001);
    group.add(mesh);
    textMeshes.push(mesh);
  });

  group.position.set(position[0], position[1], position[2]);
  group.rotation.set(rotation[0], rotation[1], rotation[2]);
  group.scale.set(scale[0], scale[1], scale[2]);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    textMeshes.forEach((m) => {
      if (m.geometry) m.geometry.dispose();
      if (m.material) m.material.dispose();
    });
  };

  return group;
}
